  const compressImage = (file, onProgress) => new Promise((resolve, reject) => {
    // NEW: Skip compression entirely if the file is already under 1MB
    if (file.size <= 1048576) {
      const reader = new FileReader();
      reader.onload = () => {
        if (onProgress) onProgress(100);
        resolve(reader.result); // Return the uncompressed Base64
      };
      reader.onerror = (err) => reject(err);
      reader.readAsDataURL(file);
      return;
    }

    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = async (event) => {
      const img = new Image();
      img.src = event.target.result;
      img.onload = async () => {
        const canvas = document.createElement('canvas');
        
        let width = img.width;
        let height = img.height;

        // Optional: Safety limit so massive 10k images don't freeze the browser
        const MAX_DIM = 1800;
        if (width > MAX_DIM || height > MAX_DIM) {
          const aspect = width / height;
          if (width > height) { width = MAX_DIM; height = MAX_DIM / aspect; }
          else { height = MAX_DIM; width = MAX_DIM * aspect; }
        }

        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        
        ctx.fillStyle = '#FFFFFF';
        ctx.fillRect(0, 0, width, height);
        ctx.drawImage(img, 0, 0, width, height);
        
        let format = 'image/jpeg';
        if (canvas.toDataURL('image/webp').startsWith('data:image/webp')) {
          format = 'image/webp'; 
        }
        
        if (onProgress) onProgress(10); 
        await new Promise(r => setTimeout(r, 20)); 
        
        // Target length for ~1MB Base64 is roughly 1,390,000 characters.
        const MAX_BASE64_LENGTH = 1390000; 
        
        let dataUrl = canvas.toDataURL(format, 0.95);
        
        if (dataUrl.length > MAX_BASE64_LENGTH) {
          let minQ = 0.01; 
          let maxQ = 0.95;
          let bestUrl = dataUrl;
          
          for (let i = 0; i < 7; i++) {
            let quality = (minQ + maxQ) / 2;
            dataUrl = canvas.toDataURL(format, quality);
            
            if (onProgress) onProgress(10 + ((i + 1) / 7) * 80);
            await new Promise(r => setTimeout(r, 10)); 
            
            if (dataUrl.length > MAX_BASE64_LENGTH) {
              maxQ = quality; 
            } else {
              minQ = quality; 
              bestUrl = dataUrl; 
            }
          }
          dataUrl = bestUrl;
        }
        
        if (onProgress) onProgress(100);
        resolve(dataUrl);
      };
      img.onerror = (err) => reject(err);
    };
    reader.onerror = (err) => reject(err);
  });
