  const generateReceiptImage = (receiptText) => new Promise(resolve => {
    const lines = receiptText.split('\n');
    const SCALE = 3; // 3x resolution for HD
    const W = 520, PADDING = 28, LINE_H = 28, FONT_SIZE = 15;
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    canvas.width = W * SCALE;
    canvas.height = (lines.length * LINE_H + PADDING * 2 + 30) * SCALE;
    ctx.scale(SCALE, SCALE);

    // Background
    ctx.fillStyle = '#FAFAFA';
    ctx.fillRect(0, 0, W, canvas.height / SCALE);

    // Top green bar
    ctx.fillStyle = '#1B5E20';
    ctx.fillRect(0, 0, W, 10);

    // Bottom green bar
    ctx.fillStyle = '#1B5E20';
    ctx.fillRect(0, canvas.height / SCALE - 10, W, 10);

    lines.forEach((line, i) => {
      const clean = line.replace(/[*_▫️🧾📋👤👨‍💼📅💰]/g, '').replace(/━/g, '─').trim();
      const y = PADDING + 18 + i * LINE_H;

      if (line.includes('PURCHASE ORDER')) {
        ctx.font = `bold ${FONT_SIZE + 4}px "Courier New", monospace`;
        ctx.fillStyle = '#1B5E20';
        // Center it
        const tw = ctx.measureText(clean).width;
        ctx.fillText(clean, (W - tw) / 2, y);
      } else if (line.includes('TOTAL:')) {
        ctx.fillStyle = '#E8F5E9';
        ctx.fillRect(PADDING - 8, y - 18, W - PADDING * 2 + 16, LINE_H + 4);
        ctx.font = `bold ${FONT_SIZE + 3}px "Courier New", monospace`;
        ctx.fillStyle = '#1B5E20';
        ctx.fillText(clean, PADDING, y);
      } else if (line.includes('─') || line.includes('━')) {
        ctx.strokeStyle = '#CCCCCC';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(PADDING, y - 8);
        ctx.lineTo(W - PADDING, y - 8);
        ctx.stroke();
      } else if (line.includes('Order:') || line.includes('Customer:') || line.includes('Staff:')) {
        ctx.font = `bold ${FONT_SIZE}px "Courier New", monospace`;
        ctx.fillStyle = '#263238';
        ctx.fillText(clean, PADDING, y);
      } else if (line.trim().startsWith('₱') || line.includes('× ')) {
        ctx.font = `${FONT_SIZE - 1}px "Courier New", monospace`;
        ctx.fillStyle = '#546E7A';
        ctx.fillText(clean, PADDING + 16, y);
      } else if (line.includes('⚠️') || line.includes('left)')) {
        ctx.font = `bold ${FONT_SIZE - 1}px "Courier New", monospace`;
        ctx.fillStyle = '#C62828';
        ctx.fillText(clean, PADDING, y);
      } else if (line.startsWith('_') || line.includes('Sent via')) {
        ctx.font = `italic ${FONT_SIZE - 2}px "Courier New", monospace`;
        ctx.fillStyle = '#999';
        ctx.fillText(clean.replace(/_/g, ''), PADDING, y);
      } else {
        ctx.font = `${FONT_SIZE}px "Courier New", monospace`;
        ctx.fillStyle = '#263238';
        ctx.fillText(clean, PADDING, y);
      }
    });

    canvas.toBlob(blob => resolve(blob), 'image/png', 1.0);
  });

