  // ── EDIT ORDER MODAL ───────────────────────────────────────────────────────
  function EditOrderModal({ order, products, liveStock, onSave, onClose, isMobile }) {
    const [customer, setCustomer] = useState(order.customer || '');
    const [items, setItems] = useState([...order.items]);
    const [searchTerm, setSearchTerm] = useState('');
    const [searchResult, setSearchResult] = useState([]);

    // Search logic for adding new items
  useEffect(() => {
    if (!searchTerm) { setSearchResult([]); return; }
    const term = searchTerm.toLowerCase();
    setSearchResult(
      products
        .filter(p => p.category !== 'PDA')
        .filter(p => p.description.toLowerCase().includes(term) || p.code.toLowerCase().includes(term))
        .slice(0, 10)
    );
  }, [searchTerm, products]);

    const handleItemChange = (index, field, value) => {
      const newItems = [...items];
      if (field === 'quantity' || field === 'price') {
        newItems[index][field] = Number(value) || 0;
      } else {
        newItems[index][field] = value;
      }
      setItems(newItems);
    };

    const removeItem = (index) => {
      if (items.length <= 1) return alert("An order must have at least one item.");
      setItems(items.filter((_, i) => i !== index));
    };

    const addNewItem = (prod) => {
      const existingIndex = items.findIndex(i => i.code === prod.code);
      if (existingIndex >= 0) {
        handleItemChange(existingIndex, 'quantity', items[existingIndex].quantity + 1);
      } else {
        setItems([...items, { code: prod.code, description: prod.description, price: safePrice(prod.price), quantity: 1 }]);
      }
      setSearchTerm('');
    };

    const handleSaveClick = () => {
      if (!customer.trim()) return alert("Customer name cannot be empty.");
      if (items.some(i => i.quantity <= 0)) return alert("All items must have a quantity of at least 1.");
      onSave(order.id, customer, items);
    };

    const total = items.reduce((s, i) => s + safePrice(i.price) * safePrice(i.quantity), 0);

    return (
      <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.6)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 300, padding: isMobile ? 10 : 20 }}>
        <div style={{ ...STYLES.card, width: '100%', maxWidth: 600, height: isMobile ? '100%' : '85vh', padding: 0, display: 'flex', flexDirection: 'column', overflow: 'hidden', borderRadius: isMobile ? 0 : 12 }}>
          
          <div style={{ padding: '16px 20px', background: COLORS.light, borderBottom: `1px solid ${COLORS.border}`, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <h3 style={{ margin: 0, color: COLORS.primary, display: 'flex', alignItems: 'center', gap: 8 }}><i className="fas fa-pen-to-square"></i> Edit Order</h3>
            <button onClick={onClose} style={{ background: 'none', border: 'none', fontSize: 22, cursor: 'pointer', color: COLORS.textLight }}><i className="fas fa-xmark"></i></button>
          </div>

          <div style={{ flex: 1, overflowY: 'auto', padding: 20, background: '#FAFAFA' }}>
            <label style={{ display: 'block', marginBottom: 6, fontWeight: 600, fontSize: 13, color: COLORS.textLight }}>Customer Name</label>
            <input value={customer} onChange={e => setCustomer(e.target.value)} style={{ ...STYLES.input, marginBottom: 20, background: 'white' }} />

            <label style={{ display: 'block', marginBottom: 6, fontWeight: 600, fontSize: 13, color: COLORS.textLight }}>Order Items</label>
            <div style={{ background: 'white', borderRadius: 8, border: `1px solid ${COLORS.border}`, padding: 10, marginBottom: 20 }}>
              {items.map((it, idx) => (
                <div key={idx} style={{ display: 'flex', gap: 10, alignItems: 'center', marginBottom: 10, paddingBottom: 10, borderBottom: idx < items.length - 1 ? '1px solid #eee' : 'none' }}>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontSize: 13, fontWeight: 600, marginBottom: 4 }}>{it.description}</div>
                    <div style={{ fontSize: 11, color: COLORS.textLight }}>{it.code}</div>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                    <div style={{ display: 'flex', flexDirection: 'column' }}>
                      <span style={{ fontSize: 10, color: COLORS.textLight }}>Price ₱</span>
                      <input type="number" value={safePrice(it.price)} onChange={e => handleItemChange(idx, 'price', e.target.value)} style={{ width: 60, padding: 5, borderRadius: 4, border: '1px solid #ccc', fontSize: 13, textAlign: 'center' }} />
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column' }}>
                      <span style={{ fontSize: 10, color: COLORS.textLight }}>Qty</span>
                      <input type="number" value={it.quantity} onChange={e => handleItemChange(idx, 'quantity', e.target.value)} style={{ width: 45, padding: 5, borderRadius: 4, border: '1px solid #ccc', fontSize: 13, textAlign: 'center' }} />
                    </div>
                    <button onClick={() => removeItem(idx)} style={{ color: COLORS.danger, background: 'none', border: 'none', marginTop: 15, cursor: 'pointer' }}><i className="fas fa-trash"></i></button>
                  </div>
                </div>
              ))}
            </div>

            <label style={{ display: 'block', marginBottom: 6, fontWeight: 600, fontSize: 13, color: COLORS.textLight }}>Add New Item</label>
            <div style={{ position: 'relative' }}>
              <i className="fas fa-search" style={{ position: 'absolute', left: 12, top: 12, color: COLORS.textLight, fontSize: 13 }}></i>
              <input placeholder="Search product to add..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} style={{ ...STYLES.input, paddingLeft: 35, background: 'white' }} />
              {searchResult.length > 0 && (
                <div style={{ position: 'absolute', top: '100%', left: 0, right: 0, background: 'white', border: `1px solid ${COLORS.border}`, borderRadius: 6, boxShadow: '0 4px 12px rgba(0,0,0,0.15)', zIndex: 10, maxHeight: 150, overflowY: 'auto', marginTop: 4 }}>
                  {searchResult.map((p) => {
    const stockKey = p.category === 'PDA' ? `PDA_${p.code}` : p.code;
    const stock = liveStock?.[stockKey] || 0;
    return (
      <div key={p.id} onClick={() => addNewItem(p)} style={{ padding: 10, borderBottom: '1px solid #eee', cursor: 'pointer', fontSize: 13, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div>
          <div>{p.description} <span style={{ color: '#888', fontSize: 11 }}>({p.code})</span></div>
          <div style={{ marginTop: 2 }}>
            <span style={{ fontSize: 11, fontWeight: 700, color: stock >= 20 ? COLORS.success : stock > 0 ? COLORS.warning : COLORS.danger, display: 'inline-flex', alignItems: 'center', gap: 3 }}>
              <i className={`fas ${stock >= 20 ? 'fa-circle-check' : stock > 0 ? 'fa-triangle-exclamation' : 'fa-circle-xmark'}`} style={{ fontSize: 10 }}></i>
              {stock >= 20 ? `Stock: ${stock}` : stock > 0 ? `Low: ${stock}` : 'Out of Stock'}
            </span>
          </div>
        </div>
        <span style={{ color: COLORS.primary, fontWeight: 'bold', flexShrink: 0, marginLeft: 10 }}>₱{safePrice(p.price).toFixed(2)}</span>
      </div>
    );
  })}
                </div>
              )}
            </div>
          </div>

          <div style={{ padding: '15px 20px', borderTop: `1px solid ${COLORS.border}`, background: COLORS.white, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <div style={{ fontWeight: 700, fontSize: 18, color: COLORS.primary }}>Total: ₱{total.toFixed(2)}</div>
            <div style={{ display: 'flex', gap: 10 }}>
              <button onClick={onClose} style={{ ...STYLES.btnSecondary }}>Cancel</button>
              <button onClick={handleSaveClick} style={{ ...STYLES.btnPrimary }}><i className="fas fa-save"></i> Save</button>
            </div>
          </div>

        </div>
      </div>
    );
  }

