// ── MATEEN ORDER IMPORT MODAL ─────────────────────────────────────────────
function MateenImportModal({ db, storage, staffList, products, liveStock, onClose, isMobile, generateReceiptImage }) {
  const [source, setSource] = useState('All Users');
  const [months, setMonths] = useState(1);
  const [isImporting, setIsImporting] = useState(false);
  const [statusText, setStatusText] = useState('');
  const [progress, setProgress] = useState(0);
  const [summary, setSummary] = useState(null);
  const [generatedPoblobs, setGeneratedPoblobs] = useState([]);
  const [importedOrdersData, setImportedOrdersData] = useState([]);
  const [estimatedTimeLeft, setEstimatedTimeLeft] = useState(0);
  
  const [savedZips, setSavedZips] = useState([]);
  const [showSavedZipsView, setShowSavedZipsView] = useState(false);

  const users = [...new Set(staffList.map(s => s.name))].filter(n => n !== 'Mateen' && n !== 'Super Admin');

  useEffect(() => {
    const q = query(collection(db, 'mateen_saved_zips'), orderBy('timestamp', 'desc'));
    const unsub = onSnapshot(q, snap => {
      setSavedZips(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    return () => unsub();
  }, [db]);

  const getRandomWorkingDate = (startTs, endTs) => {
    let valid = false;
    let randomDate;
    while (!valid) {
      const ts = startTs + Math.random() * (endTs - startTs);
      randomDate = new Date(ts);
      if (randomDate.getDay() !== 0) valid = true; 
    }
    const startMin = 8 * 60 + 30; 
    const endMin = 17 * 60;       
    const totalMin = Math.floor(Math.random() * (endMin - startMin + 1)) + startMin;
    randomDate.setHours(Math.floor(totalMin / 60), totalMin % 60, 0, 0);
    return randomDate;
  };

  const formatMateenPO = (order, importedDate) => {
    const itemsList = order.items || [];
    const lines = itemsList.map(i => {
      const prod = products?.find(p => p.code === i.code);
      const stock = liveStock?.[i.code] || 0;
      const stockNote = prod?.category === 'PDA' && stock <= 3 ? ` ⚠️(${stock} left)` : '';
      return `▫️ ${i.quantity}x *${i.description}*${stockNote}\n    ₱${safePrice(i.price).toFixed(2)} × ${i.quantity} = ₱${(safePrice(i.price) * i.quantity).toFixed(2)}`;
    }).join('\n');
    
    const formattedDate = importedDate.toLocaleString('en-US', { timeZone: 'Asia/Manila', month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' });
    
    return `🧾 *PURCHASE ORDER*\n🏢 *Wilcare Trading Corp.*\n━━━━━━━━━━━━━━━━━━\n👤 Customer: *${order.customer}*\n👨‍💼 Username: *Mateen*\n📅 ${formattedDate}\n━━━━━━━━━━━━━━━━━━\n${lines}\n━━━━━━━━━━━━━━━━━━\n💰 *TOTAL: ₱${safePrice(order.total).toFixed(2)}*\n━━━━━━━━━━━━━━━━━━\n_Sent via Wilcare POS_`;
  };

  const generateExcelReport = (ordersList, monthLabel) => {
    const excelData = [];
    
    excelData.push(["WILCARE TRADING CORP — SALES REPORT / ORDER LOG"]);
    excelData.push([monthLabel]);
    excelData.push([]);
    excelData.push(['Order ID', 'Order Date', 'Customer', 'Item Name', 'Category', 'Qty Sold', 'Unit Price', 'Total Amount', 'Payment Method', 'Order Status', 'Sales Rep']);

    ordersList.forEach(order => {
      const orderDate = new Date(order.timestamp).toISOString().split('T')[0];
      const orderId = order.customId || order.id;
      const customer = order.customer || 'Unknown';
      const status = order.status || 'Completed';
      const salesRep = order.staff || 'Mateen';

      const items = order.items || [];
      items.forEach(item => {
        const prod = products?.find(p => p.code === item.code);
        const category = prod?.category || 'Uncategorized';
        const qty = item.quantity || 0;
        const price = safePrice(item.price);
        const totalAmount = qty * price;

        excelData.push([
          orderId,
          orderDate,
          customer,
          item.description,
          category,
          qty,
          price,
          totalAmount,
          "Bank Transfer", 
          status,
          salesRep
        ]);
      });
    });

    const ws = XLSX.utils.aoa_to_sheet(excelData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Sales Report");
    
    XLSX.writeFile(wb, `Sales_Report_${monthLabel.replace(/\s+/g, '_')}.xlsx`);
  };

  const handleExportAllExcel = async () => {
    setIsImporting(true);
    setStatusText("Fetching data for Excel...");
    try {
      const q = query(collection(db, 'orders'), where('staff', '==', 'Mateen'));
      const snap = await getDocs(q);
      if (snap.empty) {
        alert("No imported orders found for Mateen.");
        setIsImporting(false);
        return;
      }
      const allOrders = snap.docs.map(d => ({ id: d.id, ...d.data() }));
      allOrders.sort((a, b) => b.timestamp - a.timestamp);
      
      generateExcelReport(allOrders, `All Time Report (${new Date().toLocaleDateString()})`);
      setIsImporting(false);
    } catch(e) {
      console.error(e);
      alert("Error: " + e.message);
      setIsImporting(false);
    }
  };

  // ✅ NEW: Download ALL Mateen P.O.s
  const handleGenerateAllMateenPOs = async () => {
    setIsImporting(true);
    setProgress(0);
    setStatusText('Fetching all your orders...');
    setEstimatedTimeLeft(0);
    
    try {
      const q = query(collection(db, 'orders'), where('staff', '==', 'Mateen'));
      const snap = await getDocs(q);
      
      if (snap.empty) {
        alert("No orders found for Mateen.");
        setIsImporting(false);
        return;
      }

      const mateenOrders = snap.docs.map(d => ({ id: d.id, ...d.data() }));
      const zip = new JSZip();
      const folderName = `All_Mateen_POs_${new Date().toLocaleDateString().replace(/\//g, '-')}`;
      const folder = zip.folder(folderName);

      setStatusText(`Generating ${mateenOrders.length} P.O. images...`);
      const processStartTime = Date.now();

      const withTimeout = (promise, ms) => Promise.race([
        promise,
        new Promise((_, reject) => setTimeout(() => reject(new Error("Timeout")), ms))
      ]);

      for (let i = 0; i < mateenOrders.length; i++) {
        const order = mateenOrders[i];
        const assignedDate = new Date(order.timestamp || order.date);
        const poText = formatMateenPO(order, assignedDate);
        
        try {
          const blob = await withTimeout(generateReceiptImage(poText), 3000);
          if (blob) {
            folder.file(`${order.customId || order.id}.png`, blob);
          }
        } catch (e) {
          console.error("Failed to generate image for", order.id);
        }

        const currentProgress = ((i + 1) / mateenOrders.length) * 80;
        setProgress(currentProgress);
        setStatusText(`Generating image ${i + 1} of ${mateenOrders.length}...`);

        const timeElapsedSec = (Date.now() - processStartTime) / 1000;
        const timePerOrder = timeElapsedSec / (i + 1);
        const remainingOrders = mateenOrders.length - (i + 1);
        setEstimatedTimeLeft(Math.round(remainingOrders * timePerOrder));

        await new Promise(r => setTimeout(r, 5));
      }

      setStatusText('Zipping files... (This may take a minute)');
      setProgress(90);
      const content = await zip.generateAsync({ type: 'blob' });
      
      saveAs(content, `${folderName}.zip`);
      
      setProgress(100);
      setIsImporting(false);
      setStatusText('');
    } catch (err) {
      console.error(err);
      alert("Failed to generate P.O.s: " + err.message);
      setIsImporting(false);
    }
  };

  const handleImport = async () => {
    if (months < 1 || !Number.isInteger(Number(months))) return alert("Please enter a valid positive integer for months.");
    if (months > 24) return alert("Maximum allowed history is 24 months.");

    setIsImporting(true);
    setSummary(null);
    setGeneratedPoblobs([]);
    setImportedOrdersData([]);
    setEstimatedTimeLeft(0);

    try {
      const now = new Date();
      const endOfLastMonth = new Date(now.getFullYear(), now.getMonth(), 0, 23, 59, 59);
      const startDate = new Date(now.getFullYear(), now.getMonth() - months, 1, 0, 0, 0);
      
      const startTs = startDate.getTime();
      const endTs = endOfLastMonth.getTime();

      setStatusText('Fetching ALL historical orders...');
      setProgress(10);

      const ordersRef = collection(db, 'orders');
      const snap = await getDocs(ordersRef);
      let sourceOrders = snap.docs.map(d => ({ id: d.id, ...d.data() }));

      sourceOrders = sourceOrders.filter(o => {
        const isValid = o.status === 'Completed' || o.status === 'In Progress';
        const isTargetUser = source === 'All Users' ? o.staff !== 'Mateen' : o.staff === source;
        return isValid && isTargetUser;
      });

      setStatusText('Checking for duplicates...');
      setProgress(20);

      const mateenImports = snap.docs
        .map(d => d.data())
        .filter(o => o.staff === 'Mateen' && o.isImported === true);
      const importedSourceIds = new Set(mateenImports.map(o => o.sourceOrderId));

      const eligibleOrders = sourceOrders.filter(o => !importedSourceIds.has(o.id));
      const alreadyImportedCount = sourceOrders.length - eligibleOrders.length;

      if (eligibleOrders.length === 0) {
        setIsImporting(false);
        setSummary({ source, months, start: startDate, end: endOfLastMonth, found: sourceOrders.length, imported: 0, skipped: alreadyImportedCount, failed: 0 });
        return;
      }

      setStatusText('Preparing to process...');
      setProgress(30);
      
      const successfulImports = [];
      const generatedBlobs = [];
      const batchWrites = [];
      const processStartTime = Date.now();
      let failedCount = 0;
      
      const startingIndex = mateenImports.length;

      const withTimeout = (promise, ms) => Promise.race([
        promise,
        new Promise((_, reject) => setTimeout(() => reject(new Error("Timeout")), ms))
      ]);

      for (let i = 0; i < eligibleOrders.length; i++) {
        try {
          const order = eligibleOrders[i];
          const assignedDate = getRandomWorkingDate(startTs, endTs);
          const importedCustomId = `MATEEN-${String(startingIndex + i).padStart(2, '0')}`;

          // ✅ FIX: Extract out the original ID so it doesn't break React lists!
          const { id: sourceId, ...orderDataWithoutId } = order;

          const newOrder = {
            ...orderDataWithoutId,
            staff: 'Mateen',
            customId: importedCustomId,
            isImported: true,
            sourceOrderId: sourceId,
            sourceUserId: order.staff,
            date: assignedDate.toISOString(),
            timestamp: assignedDate.getTime(),
            importBatchId: `batch_${processStartTime}`
          };

          const poText = formatMateenPO(newOrder, assignedDate);
          const blob = await withTimeout(generateReceiptImage(poText), 3000);
          if (!blob) throw new Error("Canvas generation failed");

          const fileName = `${importedCustomId}.png`;
          
          try {
            if (storage) {
              const storageRef = ref(storage, `Mateen_PO_Images/${fileName}`);
              await withTimeout(uploadBytes(storageRef, blob), 1500);
            }
          } catch (uploadErr) {}

          generatedBlobs.push({ name: fileName, blob });
          successfulImports.push(newOrder);
          batchWrites.push(newOrder);

        } catch (itemError) {
          console.error(`Skipped order ${i}:`, itemError);
          failedCount++;
        }

        const currentProgress = 30 + ((i + 1) / eligibleOrders.length) * 60;
        setProgress(currentProgress);
        setStatusText(`Adjusting dates: ${i + 1} of ${eligibleOrders.length}...`);

        const timeElapsedSec = (Date.now() - processStartTime) / 1000;
        const timePerOrder = timeElapsedSec / (i + 1);
        const remainingOrders = eligibleOrders.length - (i + 1);
        setEstimatedTimeLeft(Math.round(remainingOrders * timePerOrder));

        await new Promise(r => setTimeout(r, 5));
      }

      setStatusText('Saving to database...');
      setProgress(95);
      
      for (let i = 0; i < batchWrites.length; i += 400) {
        const batch = writeBatch(db);
        batchWrites.slice(i, i + 400).forEach(orderData => {
          const newDocRef = doc(collection(db, 'orders'));
          batch.set(newDocRef, orderData);
        });
        await batch.commit();
      }

      setGeneratedPoblobs(generatedBlobs);
      setImportedOrdersData(successfulImports); 
      setProgress(100);
      setSummary({ 
        source, months, start: startDate, end: endOfLastMonth, 
        found: sourceOrders.length, imported: successfulImports.length, 
        skipped: alreadyImportedCount, failed: failedCount 
      });
      setIsImporting(false);

    } catch (err) {
      console.error(err);
      alert("Import failed: " + err.message);
      setIsImporting(false);
    }
  };

  const handleDownloadZip = async () => {
    if (generatedPoblobs.length === 0) return;
    
    setIsImporting(true);
    setStatusText("Generating ZIP file...");
    setProgress(40);

    const zip = new JSZip();
    
    const monthNames = [ "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" ];
    const startStr = `${monthNames[summary.start.getMonth()]} ${summary.start.getFullYear()}`;
    const endStr = `${monthNames[summary.end.getMonth()]} ${summary.end.getFullYear()}`;
    const zipMonthLabel = summary.months === 1 ? startStr : `${startStr} to ${endStr}`;
    
    const folderName = `Mateen_Imports_${zipMonthLabel.replace(/\s+/g, '_')}`;
    const folder = zip.folder(folderName);
    
    generatedPoblobs.forEach(file => {
      folder.file(file.name, file.blob);
    });

    const content = await zip.generateAsync({ type: 'blob' });
    
    setProgress(70);
    setStatusText("Uploading backup to cloud... (This may take a minute)");
    
    const withTimeout = (promise, ms) => Promise.race([
      promise,
      new Promise((_, reject) => setTimeout(() => reject(new Error("Upload Timeout - File took too long")), ms))
    ]);

    try {
      if (storage) {
        const zipFileName = `${folderName}_${Date.now()}.zip`;
        const storagePath = `Mateen_Saved_ZIPs/${zipFileName}`;
        const zipRef = ref(storage, storagePath);
        
        await withTimeout(uploadBytes(zipRef, content), 180000); 
        const downloadUrl = await withTimeout(getDownloadURL(zipRef), 15000);

        await withTimeout(addDoc(collection(db, 'mateen_saved_zips'), {
          url: downloadUrl,
          path: storagePath,
          name: zipMonthLabel,
          source: summary.source,
          timestamp: Date.now()
        }), 15000);
      }
    } catch (e) {
      console.warn("Firebase Storage blocked ZIP upload. Bypassing to allow local download.");
    }

    setProgress(100);
    setIsImporting(false); 
    setStatusText("");
    
    saveAs(content, `${folderName}.zip`);
  };

  const handleDeleteZip = async (zipId, storagePath) => {
    if (!window.confirm("Are you sure you want to delete this saved ZIP?")) return;
    try {
      await deleteDoc(doc(db, 'mateen_saved_zips', zipId));
      if (storage && storagePath) {
        const fileRef = ref(storage, storagePath);
        await deleteObject(fileRef).catch(e => console.warn("Storage deletion blocked by rules."));
      }
    } catch (e) {
      alert("Error deleting record.");
      console.error(e);
    }
  };

  const handleDeleteAllMateenOrders = async () => {
    if (!window.confirm("⚠️ WARNING: This will PERMANENTLY DELETE ALL orders associated with Mateen. This action cannot be undone.\n\nDo you want to proceed?")) return;
    if (!window.confirm("Are you absolutely sure you want to delete ALL your imported orders?")) return;

    setIsImporting(true);
    setStatusText('Deleting all Mateen orders...');
    setProgress(10);

    try {
      const q = query(collection(db, 'orders'), where('staff', '==', 'Mateen'));
      const snap = await getDocs(q);

      if (snap.empty) {
        alert("No orders found for Mateen.");
        setIsImporting(false);
        setStatusText("");
        return;
      }

      const docsToDelete = snap.docs;
      for (let i = 0; i < docsToDelete.length; i += 400) {
        const batch = writeBatch(db);
        docsToDelete.slice(i, i + 400).forEach(d => {
          batch.delete(d.ref);
        });
        await batch.commit();
        setProgress(10 + ((i + 400) / docsToDelete.length) * 80);
        setStatusText(`Deleted ${Math.min(i + 400, docsToDelete.length)} of ${docsToDelete.length}...`);
      }

      setProgress(100);
      alert(`Successfully deleted all ${docsToDelete.length} orders belonging to Mateen.`);
      
    } catch (e) {
      console.error(e);
      alert("Error deleting orders: " + e.message);
    } finally {
      setIsImporting(false);
      setStatusText("");
    }
  };

  return (
    <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.6)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 300, padding: isMobile ? 10 : 20 }}>
      <div style={{ ...STYLES.card, width: '100%', maxWidth: 500, borderRadius: 12, padding: 0, overflow: 'hidden' }}>
        
        <div style={{ padding: '16px 20px', background: '#673AB7', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h3 style={{ margin: 0, color: 'white', display: 'flex', alignItems: 'center', gap: 8 }}>
            <i className="fas fa-file-import"></i> {showSavedZipsView ? "Saved ZIPs" : "Import Orders"}
          </h3>
          <button onClick={onClose} disabled={isImporting} style={{ background: 'none', border: 'none', fontSize: 22, cursor: 'pointer', color: 'rgba(255,255,255,0.7)' }}>
            <i className="fas fa-xmark"></i>
          </button>
        </div>

        <div style={{ padding: 25, background: '#FAFAFA', maxHeight: '80vh', overflowY: 'auto' }}>
          {showSavedZipsView ? (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 15, animation: 'slideInUp 0.2s ease' }}>
              <button onClick={() => setShowSavedZipsView(false)} style={{ background: 'none', border: 'none', color: '#673AB7', cursor: 'pointer', fontSize: 14, fontWeight: 600, display: 'flex', alignItems: 'center', gap: 6, alignSelf: 'flex-start' }}>
                <i className="fas fa-arrow-left"></i> Back to Import Tool
              </button>
              
              {savedZips.length === 0 ? (
                <div style={{ textAlign: 'center', padding: '40px 20px', color: COLORS.textLight }}>
                  <i className="fas fa-folder-open" style={{ fontSize: 40, marginBottom: 12, opacity: 0.3 }}></i>
                  <div style={{ fontWeight: 600 }}>No saved ZIPs found.</div>
                  <div style={{ fontSize: 12, marginTop: 4 }}>Completed imports will appear here.</div>
                </div>
              ) : (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                  {savedZips.map(zip => (
                    <div key={zip.id} style={{ background: 'white', padding: '14px 16px', borderRadius: 8, border: `1px solid ${COLORS.border}`, display: 'flex', flexDirection: 'column', gap: 10 }}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                        <div>
                          <div style={{ fontWeight: 600, color: COLORS.text, fontSize: 14, display: 'flex', alignItems: 'center', gap: 6 }}>
                            <i className="fas fa-file-zipper" style={{ color: '#2196F3' }}></i> {zip.name}
                          </div>
                          <div style={{ fontSize: 11, color: COLORS.textLight, marginTop: 4 }}>
                            Source: {zip.source} • {new Date(zip.timestamp).toLocaleDateString()}
                          </div>
                        </div>
                      </div>
                      <div style={{ display: 'flex', gap: 8, marginTop: 4 }}>
                        <a href={zip.url} target="_blank" rel="noreferrer" style={{ ...STYLES.btnSecondary, flex: 1, justifyContent: 'center', padding: '8px 12px', fontSize: 12, textDecoration: 'none' }}>
                          <i className="fas fa-download"></i> Download
                        </a>
                        <button onClick={() => handleDeleteZip(zip.id, zip.path)} style={{ ...STYLES.btnDanger, padding: '8px 12px', fontSize: 12 }}>
                          <i className="fas fa-trash"></i>
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          ) : !summary ? (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 15 }}>
              <div>
                <label style={{ display: 'block', marginBottom: 6, fontWeight: 600, fontSize: 13, color: COLORS.text }}>Import Orders From</label>
                <select value={source} onChange={e => setSource(e.target.value)} disabled={isImporting} style={{ ...STYLES.input, background: 'white', cursor: 'pointer' }}>
                  <option value="All Users">All Users</option>
                  {users.map(u => <option key={u} value={u}>{u}</option>)}
                </select>
              </div>

              <div>
                <label style={{ display: 'block', marginBottom: 6, fontWeight: 600, fontSize: 13, color: COLORS.text }}>Adjust All Historical Orders Into (Months)</label>
                <input 
                  type="number" 
                  min="1" max="24" step="1"
                  value={months} 
                  onChange={e => setMonths(Number(e.target.value))} 
                  disabled={isImporting}
                  style={{ ...STYLES.input, background: 'white' }} 
                />
                <div style={{ fontSize: 11, color: COLORS.textLight, marginTop: 4 }}>Note: Current month is automatically excluded.</div>
              </div>

              {isImporting ? (
                <div style={{ marginTop: 10, textAlign: 'center' }}>
                  <div style={{ fontSize: 13, fontWeight: 600, color: '#673AB7', marginBottom: 8 }}>
                    <i className="fas fa-spinner fa-spin"></i> {statusText} {Math.round(progress)}%
                  </div>
                  <div style={{ width: '100%', height: 8, background: '#E0E0E0', borderRadius: 4, overflow: 'hidden' }}>
                    <div style={{ width: `${progress}%`, height: '100%', background: '#673AB7', transition: 'width 0.3s ease' }} />
                  </div>
                  {progress > 10 && estimatedTimeLeft > 0 && progress < 90 && (
                    <div style={{ fontSize: 12, color: COLORS.textLight, marginTop: 8, display: 'flex', justifyContent: 'center', alignItems: 'center', gap: 5 }}>
                      <i className="fas fa-clock"></i> ~{estimatedTimeLeft}s remaining
                    </div>
                  )}
                </div>
              ) : (
                <>
                  <div style={{ display: 'flex', gap: 10, marginTop: 10 }}>
                    <button onClick={handleExportAllExcel} style={{ ...STYLES.btnPrimary, background: '#2E7D32', border: 'none', flex: 1, padding: 14, justifyContent: 'center' }}>
                      <i className="fas fa-file-excel"></i> Export Excel
                    </button>
                    <button onClick={handleImport} style={{ ...STYLES.btnPrimary, background: '#673AB7', border: 'none', flex: 1, padding: 14, justifyContent: 'center' }}>
                      <i className="fas fa-play"></i> Import Orders
                    </button>
                  </div>

                  <div style={{ borderTop: `1px solid ${COLORS.border}`, marginTop: 10, paddingTop: 15, display: 'flex', gap: 10, flexWrap: 'wrap' }}>
                    {/* ✅ NEW: DOWNLOAD ALL MY P.O.S BUTTON */}
                    <button onClick={handleGenerateAllMateenPOs} style={{ ...STYLES.btnPrimary, background: '#1976D2', border: 'none', flex: '1 1 100%', padding: 12, justifyContent: 'center' }}>
                      <i className="fas fa-file-zipper"></i> Download All My P.O.s
                    </button>
                    <button onClick={() => setShowSavedZipsView(true)} style={{ ...STYLES.btnSecondary, flex: 1, padding: 12, justifyContent: 'center', color: '#673AB7', borderColor: '#673AB7' }}>
                      <i className="fas fa-box-archive"></i> Manage ZIPs ({savedZips.length})
                    </button>
                    <button onClick={handleDeleteAllMateenOrders} style={{ ...STYLES.btnDanger, flex: 1, padding: 12, justifyContent: 'center' }}>
                      <i className="fas fa-trash"></i> Delete My Orders
                    </button>
                  </div>
                </>
              )}
            </div>
          ) : (
            <div style={{ animation: 'slideInUp 0.3s ease' }}>
              <div style={{ textAlign: 'center', marginBottom: 20 }}>
                <i className="fas fa-circle-check" style={{ fontSize: 40, color: COLORS.success, marginBottom: 10 }}></i>
                <h3 style={{ margin: 0, color: COLORS.text }}>Import Complete</h3>
              </div>
              
              <div style={{ background: 'white', border: `1px solid ${COLORS.border}`, borderRadius: 8, padding: 15, fontSize: 13, display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 20 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between' }}><strong>Source:</strong> <span>{summary.source}</span></div>
                <div style={{ display: 'flex', justifyContent: 'space-between' }}><strong>Date Target:</strong> <span>{summary.start.toLocaleDateString()} – {summary.end.toLocaleDateString()}</span></div>
                <hr style={{ border: 'none', borderTop: `1px dashed ${COLORS.border}`, margin: '4px 0' }} />
                <div style={{ display: 'flex', justifyContent: 'space-between' }}><strong>Historical Found:</strong> <span>{summary.found}</span></div>
                <div style={{ display: 'flex', justifyContent: 'space-between' }}><strong>Already Imported:</strong> <span style={{ color: COLORS.warning }}>{summary.skipped}</span></div>
                {summary.failed > 0 && <div style={{ display: 'flex', justifyContent: 'space-between' }}><strong>Failed to Gen:</strong> <span style={{ color: COLORS.danger }}>{summary.failed}</span></div>}
                <div style={{ display: 'flex', justifyContent: 'space-between', color: COLORS.success }}><strong>Successfully Adjusted:</strong> <strong>{summary.imported}</strong></div>
              </div>

              {isImporting ? (
                <div style={{ textAlign: 'center', padding: '15px 0' }}>
                  <div style={{ fontSize: 13, fontWeight: 600, color: '#2196F3', marginBottom: 8 }}><i className="fas fa-spinner fa-spin"></i> {statusText}</div>
                </div>
              ) : (
                <div style={{ display: 'flex', gap: 10 }}>
                  <button onClick={handleDownloadZip} disabled={generatedPoblobs.length === 0} style={{ ...STYLES.btnPrimary, background: '#2196F3', border: 'none', flex: 1, padding: 14, justifyContent: 'center', opacity: generatedPoblobs.length === 0 ? 0.5 : 1 }}>
                    <i className="fas fa-file-zipper"></i> Download ZIP
                  </button>
                  <button onClick={() => {
                    const monthNames = [ "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" ];
                    const startStr = `${monthNames[summary.start.getMonth()]} ${summary.start.getFullYear()}`;
                    const endStr = `${monthNames[summary.end.getMonth()]} ${summary.end.getFullYear()}`;
                    const zipMonthLabel = summary.months === 1 ? startStr : `${startStr} to ${endStr}`;
                    generateExcelReport(importedOrdersData, zipMonthLabel);
                  }} style={{ ...STYLES.btnPrimary, background: '#2E7D32', border: 'none', flex: 1, padding: 14, justifyContent: 'center' }}>
                    <i className="fas fa-file-excel"></i> Export Excel
                  </button>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}